head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > E > onsubtotaldblclick]<br/>SubTotal Cell 영역을 마우스 왼쪽 버튼으로 더블 클릭할 때 발생합니다.",
    "validation" : [
        "info.colID 는 더블 클릭된 SubTotal Cell 의 Column ID 값을 갖습니다.",
        "info.startRowIndex 는 더블 클릭된 SubTotal Cell 의 부분합 그룹이 시작된 Row 의 인덱스값을 갖습니다.",
        "info.endRowIndex 는 더블 클릭된 SubTotal Cell 의 부분합 그룹이 끝난 Row 의 인덱스값을 갖습니다.",
        "info.element 는 더블 클릭된 SubTotal Cell 의 DOM Element 참조를 갖습니다.",
        "RowNum, RowStatus Column 의 SubTotal 영역에서도 이벤트가 발생합니다.",
        "onsubtotalclick 이벤트가 한 번 발생한 후 onsubtotaldblclick 이벤트가 발생합니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성 (비동기 dynamicCreate 완료까지 대기)
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - onsubtotaldblclick 검증용 : Header + SubTotal(dept 그룹 소계) + Footer(합계) 를 모두 갖춘 커스텀 GridView 동적 생성
//    (createBasicGridView 는 SubTotal 미생성이라 onsubtotaldblclick 검증 불가)
//  - rowNumVisible/rowStatusVisible=true : RowNum, RowStatus Column 의 SubTotal 영역 더블클릭에서도 발생 확인(@spec1)
//  - onsubtotalclick 도 함께 바인딩 : 더블클릭 시 onsubtotalclick 발생 후 onsubtotaldblclick 발생 순서 확인(@spec2)
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    //  - 더블클릭은 사용자 액션으로 수행되므로 라벨로 조작 방법을 안내
    $c.gcm.createLabel('label="[전제] 그룹(dept) SubTotal(소계) + RowNum/RowStatus Column 을 갖춘 그리드.\n[절차] SubTotal(부분합) 셀을 마우스 좌측으로 더블클릭하세요. -> onsubtotaldblclick 발생(info.colID / startRowIndex / endRowIndex / element 출력).\n[확인] 결과창 ▶ 출력 순서가 onsubtotalclick -> onsubtotaldblclick 인지, RowNum/RowStatus Column 의 SubTotal 영역 더블클릭에서도 동일하게 발생하는지 확인."', '', 'label1');

    // GridView 와 바인딩할 DataList 동적 생성
    //  - dept(그룹 기준), amount(소계/합계 대상 number)
    //  - SubTotal 은 targetColumnID(=dept) 값이 바뀌는 지점마다 소계 Row 삽입되므로 같은 dept 가 연속되도록 정렬된 데이터 사용
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="dept" name="dept" dataType="text"></w2:column>';
    strDlt += '<w2:column id="amount" name="amount" dataType="number"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    // 데이터 5건 (Sales 2건 + Dev 2건 + QA 1건) -> dept 그룹 3개 -> SubTotal Row 3개 생성됨
    let jsonData = [
        { "name": "John", "dept": "Sales", "amount": 100 },
        { "name": "Jane", "dept": "Sales", "amount": 200 },
        { "name": "Mike", "dept": "Dev",   "amount": 300 },
        { "name": "Amy",  "dept": "Dev",   "amount": 400 },
        { "name": "Tom",  "dept": "QA",    "amount": 500 }
    ];
    dlt_bind.setJSON(jsonData, false);

    // Property 설정은 createCList 공통 함수 사용
    //  - rowNumVisible/rowStatusVisible=true : RowNum, RowStatus Column 의 SubTotal 영역 더블클릭에서도 발생 확인(@spec1)
    let properties = {
        dataList: "data:dlt_bind",
        rowNumVisible: "true",
        rowStatusVisible: "true"
    };
    let cList = $c.gcm.createCList(properties);

    // 이벤트 핸들러 부착 (createEList 공통 함수)
    //  - onsubtotalclick 도 함께 바인딩하여 더블클릭 시 발생 순서(@spec2) 검증
    let eList = $c.gcm.createEList(["onsubtotalclick", "onsubtotaldblclick"]);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    // Header(이름/부서/금액) + gBody(데이터) + Footer(합계) + SubTotal(부서별 소계)
    // - Footer : amount 컬럼에 sum('amount') expression -> 전체 합계 Row (Body 아래 별도 영역)
    // - SubTotal : targetColumnID="dept" -> dept 가 바뀔 때마다 소계 Row 삽입, amount 에 sum('amount') expression
    // - 마지막 컬럼 width="*" 로 가로 스크롤 방지
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' ' + eList + ' id="" style="width:600px;height:420px;">';
    strTarget += '<w2:caption style="" id="caption1" value="onsubtotaldblclick (SubTotal Cell 좌측 더블클릭) 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="160" style="" inputType="text" id="hcol1" value="이름"></w2:column>';
    strTarget += '<w2:column width="160" style="" inputType="text" id="hcol2" value="부서"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol3" value="금액"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="160" style="" inputType="text" id="name" dataList="name"></w2:column>';
    strTarget += '<w2:column width="160" style="" inputType="text" id="dept" dataList="dept"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" dataType="number" displayFormat="#,###" id="amount" dataList="amount"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    // Footer : 전체 합계 Row
    strTarget += '<w2:footer style="" id="footer1">';
    strTarget += '<w2:row style="" id="frow1">';
    strTarget += '<w2:column width="160" style="" inputType="text" id="fcol1" value="합계(Footer)"></w2:column>';
    strTarget += '<w2:column width="160" style="" inputType="text" id="fcol2" value=""></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="expression" dataType="number" displayFormat="#,###" id="fcol3" expression="sum(\'amount\')"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:footer>';
    // SubTotal : dept 기준 소계 Row (dept 값이 바뀌는 지점마다 삽입)
    strTarget += '<w2:subTotal style="" id="subTotal1" targetColumnID="dept">';
    strTarget += '<w2:row style="" id="srow1">';
    strTarget += '<w2:column width="160" style="" inputType="text" id="scol1" value="소계(SubTotal)"></w2:column>';
    strTarget += '<w2:column width="160" style="" inputType="text" id="scol2" value=""></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="expression" dataType="number" displayFormat="#,###" id="scol3" expression="sum(\'amount\')"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:subTotal>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate('target1', 'gridView', strTarget, grp_comp);
}



// onsubtotalclick : SubTotal Cell 좌클릭 시 발생 (@spec2 발생 순서 검증용)
//  - 더블클릭 시 onsubtotalclick 이 먼저 발생함을 확인하기 위해 함께 바인딩
//  - 발생 즉시 한 줄 출력(출력 라인 순서 = 발생 순서)
scwin.target1_onsubtotalclick = function (info) {
    wf_body_bottom.getObj("scwin").setReturnValue("▶ onsubtotalclick info.colID : " + (info && info.colID) + ", startRowIndex : " + (info && info.startRowIndex) + ", endRowIndex : " + (info && info.endRowIndex));
};



// onsubtotaldblclick : SubTotal Cell 좌측 더블클릭 시 발생 (검증 대상)
//  - 엔진 시그니처 : event.fireEvent(this, "onsubtotaldblclick", info)  -> 핸들러는 info 객체 하나만 받음
//  - info = { colID, startRowIndex, endRowIndex, element }
//  - info.element 는 DOM 참조이므로 한 줄로만 출력(개별 속성 나열 금지)
scwin.target1_onsubtotaldblclick = function (info) {
    wf_body_bottom.getObj("scwin").setReturnValue("▶ onsubtotaldblclick info.colID : " + (info && info.colID));
    wf_body_bottom.getObj("scwin").setReturnValue("info.startRowIndex : " + (info && info.startRowIndex));
    wf_body_bottom.getObj("scwin").setReturnValue("info.endRowIndex : " + (info && info.endRowIndex));
    wf_body_bottom.getObj("scwin").setReturnValue("info.element : " + (info && info.element && info.element.tagName));
};
